<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Bouncing Ball Physics Playground</title>
    <style>
        body {
            margin: 0;
            padding: 20px;
            background-color: #1a1a1a; /* Dark theme */
            color: #ffffff;
            font-family: sans-serif;
            display: flex;
            flex-direction: column;
            align-items: center;
        }

        h1 {
            margin-bottom: 20px;
            font-weight: normal;
            letter-spacing: 2px;
        }

        .controls {
            margin-bottom: 20px;
            display: flex;
            gap: 10px;
        }

        button {
            padding: 10px 20px;
            background-color: #333;
            color: white;
            border: none;
            border-radius: 4px;
            cursor: pointer;
            font-size: 16px;
            transition: background-color 0.2s, transform 0.1s;
        }

        button:hover {
            background-color: #555;
        }

        button:active {
            transform: scale(0.98);
        }

        #sim-container {
            position: relative;
            border-radius: 4px;
            overflow: hidden;
            box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5);
        }

        canvas {
            display: block;
            background-color: #2d2d2d; /* Darker canvas */
        }
    </style>
</head>
<body>
    <h1>Bouncing Ball Physics Playground</h1>

    <div class="controls">
        <button id="drop">Drop a new ball</button>
        <button id="play">Pause</button>
        <button id="clear">Clear all balls</button>
    </div>

    <div id="sim-container">
        <canvas id="sim" width="500" height="500"></canvas>
    </div>

    <script>
        // Get canvas and context
        const canvas = document.getElementById('sim');
        const ctx = canvas.getContext('2d');

        // Configuration parameters
        const GRAVITY = 0.4;
        const RESTITUTION = 0.85; // Energy loss on bounce (1.0 = no energy loss)
        const FRICTION = 0.995;   // Air resistance

        // State
        let balls = [];
        let animationId = null;
        let isPlaying = true;

        // Set canvas dimensions (CSS pixels match internal resolution)
        const CANVAS_WIDTH = 500;
        const CANVAS_HEIGHT = 500;
        canvas.width = CANVAS_WIDTH;
        canvas.height = CANVAS_HEIGHT;

        // Expose the API on window
        window.sim = {
            w: CANVAS_WIDTH,
            h: CANVAS_HEIGHT,

            balls: () => {
                return balls.map(ball => ({ x: ball.x, y: ball.y, vx: ball.vx, vy: ball.vy, r: ball.r }));
            },

            addBall: (x, y, vx = 0, vy = 0, r) => {
                const radius = r || Math.random() * 15 + 10; // Random radius between 10 and 25
                balls.push({
                    x,
                    y,
                    vx,
                    vy,
                    r: radius,
                    color: `hsl(${Math.random() * 360}, 70%, 60%)` // Random bright color
                });
            },

            clear: () => {
                balls = [];
            },

            step: (dt = 1) => {
                for (let ball of balls) {
                    // Apply gravity
                    ball.vy += GRAVITY * dt;

                    // Apply air resistance
                    ball.vx *= FRICTION;
                    ball.vy *= FRICTION;

                    // Update position
                    ball.x += ball.vx * dt;
                    ball.y += ball.vy * dt;

                    // Check for wall collisions (left and right)
                    if (ball.x - ball.r < 0) {
                        ball.x = ball.r; // Clamp to edge
                        ball.vx = -ball.vx * RESTITUTION;
                    } else if (ball.x + ball.r > CANVAS_WIDTH) {
                        ball.x = CANVAS_WIDTH - ball.r; // Clamp to edge
                        ball.vx = -ball.vx * RESTITUTION;
                    }

                    // Check for floor and ceiling collisions
                    if (ball.y - ball.r < 0) {
                        ball.y = ball.r; // Clamp to top
                        ball.vy = -ball.vy * RESTITUTION;
                    } else if (ball.y + ball.r > CANVAS_HEIGHT) {
                        ball.y = CANVAS_HEIGHT - ball.r; // Clamp to bottom
                        ball.vy = -ball.vy * RESTITUTION;

                        // Prevent micro-bouncing when near rest on the floor
                        if (Math.abs(ball.vy) < GRAVITY * 2) {
                            ball.vy = 0;
                        }
                    }
                }
            },

            draw: () => {
                // Clear canvas with dark background
                ctx.fillStyle = '#2d2d2d';
                ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

                // Draw each ball
                for (let ball of balls) {
                    ctx.beginPath();
                    ctx.arc(ball.x, ball.y, ball.r, 0, Math.PI * 2);
                    ctx.fillStyle = ball.color;
                    ctx.fill();

                    // Add a subtle highlight for better visual appeal
                    ctx.beginPath();
                    ctx.arc(ball.x - ball.r * 0.3, ball.y - ball.r * 0.3, ball.r * 0.25, 0, Math.PI * 2);
                    ctx.fillStyle = 'rgba(255, 255, 255, 0.3)';
                    ctx.fill();
                }
            }
        };

        // Animation loop
        function animate() {
            if (isPlaying) {
                window.sim.step();
                window.sim.draw();
            }
            animationId = requestAnimationFrame(animate);
        }

        // Start the simulation
        animate();

        // Button event handlers
        document.getElementById('drop').addEventListener('click', () => {
            // Drop a ball from the top center with slight random horizontal velocity
            const x = CANVAS_WIDTH / 2 + (Math.random() * 40 - 20);
            window.sim.addBall(x, 50, Math.random() * 10 - 5, 0, Math.random() * 15 + 10);
        });

        document.getElementById('play').addEventListener('click', () => {
            isPlaying = !isPlaying;
            this.textContent = isPlaying ? 'Pause' : 'Play';
        });

        document.getElementById('clear').addEventListener('click', () => {
            window.sim.clear();
        });

        // Add ball on canvas click
        canvas.addEventListener('click', (e) => {
            const rect = canvas.getBoundingClientRect();
            const x = e.clientX - rect.left;
            const y = e.clientY - rect.top;

            // Randomize velocity a bit for more interesting behavior
            window.sim.addBall(x, y, Math.random() * 10 - 5, Math.random() * 10 - 5);
        });
    </script>
</body>
</html>
